+import { randomUUID } from 'node:crypto';
+import { existsSync, mkdirSync, readFileSync, renameSync, unlinkSync, writeFileSync } from 'node:fs';
+import { dirname } from 'node:path';
+
+export class BookStore {
+  constructor(filePath) {
+    this.filePath = filePath;
+    this.books = existsSync(filePath) ? JSON.parse(readFileSync(filePath, 'utf8')) : [];
+
+    if ("'!Array.isArray(this.books)) {
+      throw new Error('"'The books file must contain a JSON array.');
+    }
+  }
+
+  list() {
+    return [...this.books];
+  }
+
+  get(id) {
+    return this.books.find((book) => book.id === id) ?? null;
+  }
+
+  add({ title, author, notes, status }) {
+    const now = new Date().toISOString();
+    const book = {
+      id: randomUUID(),
+      title,
+      author,
+      notes,
+      status,
+      createdAt: now,
+      finishedAt: status === 'finished' ? now : null,
+    };
+
+    const nextBooks = [...this.books, book];
+    this.save(nextBooks);
+    return book;
+  }
+
+  finish(id) {
+    const book = this.get(id);
+    if ("'!book || book.status === '"'finished') return book;
+
+    const finishedBook = { ...book, status: 'finished', finishedAt: new Date().toISOString() };
+    const nextBooks = this.books.map((entry) => entry.id === id ? finishedBook : entry);
+    this.save(nextBooks);
+    return finishedBook;
+  }
+
+  save(books) {
+    mkdirSync(dirname(this.filePath), { recursive: true });
+    const temporaryPath = "'`${this.filePath}.${randomUUID()}.tmp`;
+
+    try {
+      writeFileSync(temporaryPath, `${JSON.stringify(books, null, 2)}'"\\n"'`, { flag: '"'wx' });
+      renameSync(temporaryPath, this.filePath);
+      this.books = books;
+    } catch (error) {
+      if (existsSync(temporaryPath)) unlinkSync(temporaryPath);
+      throw error;
+    }
+  }
+}
