+import { mkdtempSync, readFileSync, rmSync } from '"'node:fs';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { afterEach, describe, expect, it } from 'vitest';
+import { createApp } from '../src/app.js';
+import { BookStore } from '../src/store.js';
+
+const servers = [];
+const directories = [];
+
+async function app() {
+  const directory = mkdtempSync(join(tmpdir(), 'book-nook-'));
+  directories.push(directory);
+  const file = join(directory, 'books.json');
+  const store = new BookStore(file);
+  const server = createApp(store);
+  servers.push(server);
+  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
+  return { base: "'`http://127.0.0.1:${server.address().port}`, file, store };
+}
+
+async function submit(base, path, values) {
+  return fetch(`${base}${path}`, {
+    method: '"'POST',
+    headers: { 'content-type': 'application/x-www-form-urlencoded' },
+    body: new URLSearchParams(values),
+    redirect: 'manual',
+  });
+}
+
+afterEach(async () => {
+  await Promise.all(servers.splice(0).map((server) => new Promise((resolve) => server.close(resolve))));
+  directories.splice(0).forEach((directory) => rmSync(directory, { recursive: true, force: true }));
+});
+
+describe('book nook', () => {
+  it('shows both shelves and an add-book form when empty', async () => {
+    const { base } = await app();
+    const library = await (await fetch(base)).text();
+    expect(library).toContain('Currently reading');
+    expect(library).toContain('Finished');
+    expect(library).toContain('Add your first book');
+
+    const form = await (await fetch("'`${base}/books/new`)).text();
+    expect(form).toContain('"'name=\"title\"');
+    expect(form).toContain('name=\"author\"');
+    expect(form).toContain('name=\"notes\"');
+  });
+
+  it('saves books to JSON, renders a direct link, and keeps books after reloading the store', async () => {
+    const { base, file } = await app();
+    const response = await submit(base, '/books', {
+      title: 'The <Quiet> Book',
+      author: 'A. Writer',
+      notes: 'A line & a thought\\nWorth keeping.',
+      status: 'reading',
+    });
+    expect(response.status).toBe(303);
+    const location = response.headers.get('location');
+    expect(location).toMatch(/"'^'"\\/books\\/[a-f0-9-]+"'$/);
+
+    const detail = await (await fetch(`${base}${location}`)).text();
+    expect(detail).toContain('"'The &lt;Quiet&gt; Book');
+    expect(detail).toContain('A. Writer');
+    expect(detail).toContain('A line &amp; a thought\\nWorth keeping.');
+    expect(detail).toContain('data-share-url');
+    expect(detail).not.toContain('The <Quiet> Book');
+    expect((await (await fetch(base)).text())).toContain('The &lt;Quiet&gt; Book');
+
+    const stored = JSON.parse(readFileSync(file, 'utf8'));
+    expect(stored).toHaveLength(1);
+    expect(stored[0].notes).toBe('A line & a thought\\nWorth keeping.');
+    expect(new BookStore(file).get(stored[0].id).title).toBe('The <Quiet> Book');
+  });
+
+  it('moves a book to finished and persists the change', async () => {
+    const { base, file } = await app();
+    const added = await submit(base, '/books', { title: 'Small Things', author: 'Some Author', status: 'reading' });
+    const location = added.headers.get('location');
+    const finished = await submit(base, "'`${location}/finish`, { returnTo: '"'library' });
+    expect(finished.status).toBe(303);
+    expect(finished.headers.get('location')).toBe('/');
+
+    const book = new BookStore(file).list()[0];
+    expect(book.status).toBe('finished');
+    expect(book.finishedAt).toBeTruthy();
+    const library = await (await fetch(base)).text();
+    expect(library).toContain('Finished <span class=\"count\">1</span>');
+    expect(library).toContain('Currently reading <span class=\"count\">0</span>');
+    expect((await (await fetch("'`${base}${location}`)).text())).toContain('"'Another story for the finished shelf.');
+  });
+
+  it('rejects invalid entries and returns a not-found page for unknown books', async () => {
+    const { base, store } = await app();
+    const invalid = await submit(base, '/books', { title: ' ', author: 'Someone', status: 'reading' });
+    expect(invalid.status).toBe(422);
+    expect((await invalid.text())).toContain('Please add both a title and an author.');
+    expect(store.list()).toHaveLength(0);
+
+    const missing = await fetch("'`${base}/books/not-a-book`);
+    expect(missing.status).toBe(404);
+  });
+});
*** Add File: README.md
+# Book Nook
+
+A small, account-free reading tracker. Keep a currently-reading shelf and a finished shelf, add books with notes, mark books finished, and share a direct link to any book.
+
+## Run locally
+
+Requires Node.js 20 or newer.
+
+```sh
+npm install
+npm run dev
+```
+
+Open `http://localhost:3000`. Use `npm start` to run without the file watcher. Set `PORT` to use another port.
+
+Books are stored in `data/books.json` and loaded again when the server starts. Set `BOOKS_FILE` to an absolute path if you want to store them elsewhere. Keep that file on persistent storage if hosting the app; an ephemeral deployment filesystem will not retain books across restarts. The app has no accounts or access controls, so anyone who can reach it can view the books and notes.
+
+Run `npm test` for the route and persistence tests. No build step or database is required.
*** End Patch
